"""Generate reviewable CloudFormation JSON without a build framework."""
import json
from pathlib import Path


def ref(name): return {'Ref': name}
def get(name, attr): return {'Fn::GetAtt': [name, attr]}
def sub(value): return {'Fn::Sub': value}


def template():
    resources = {}
    def add(name, kind, props, why, must=None, retain=False, **extra):
        value = {'Type': 'AWS::' + kind, 'Properties': props, 'Metadata': {'com.aws.cloudformation.Context': {'why': why, 'must': must or []}}, **extra}
        if retain: value.update(DeletionPolicy='Retain', UpdateReplacePolicy='Retain')
        resources[name] = value

    def bucket(name, why, versioned=False):
        add(name, 'S3::Bucket', {'PublicAccessBlockConfiguration': {k: True for k in ['BlockPublicAcls','BlockPublicPolicy','IgnorePublicAcls','RestrictPublicBuckets']}, 'BucketEncryption': {'ServerSideEncryptionConfiguration': [{'ServerSideEncryptionByDefault': {'SSEAlgorithm': 'AES256'}}]}, **({'VersioningConfiguration': {'Status': 'Enabled'}} if versioned else {})}, why, ['Private; TLS-only; retain data on stack deletion.'], retain=True)
        add(name+'Policy', 'S3::BucketPolicy', {'Bucket': ref(name), 'PolicyDocument': {'Version': '2012-10-17', 'Statement': [{'Effect': 'Deny', 'Principal': '*', 'Action': 's3:*', 'Resource': [get(name,'Arn'), sub('${'+name+'.Arn}/*')], 'Condition': {'Bool': {'aws:SecureTransport': False}}}]}}, 'Require HTTPS for every object operation.')
    bucket('Website', 'Static export served only through CloudFront origin access control.')
    bucket('Results', 'Durable aggregated experiment results; no request traces or credentials.', True)
    add('Jobs', 'DynamoDB::Table', {'BillingMode': 'PAY_PER_REQUEST', 'AttributeDefinitions': [{'AttributeName':'owner','AttributeType':'S'}, {'AttributeName':'id','AttributeType':'S'}], 'KeySchema': [{'AttributeName':'owner','KeyType':'HASH'}, {'AttributeName':'id','KeyType':'RANGE'}], 'SSESpecification': {'SSEEnabled': True}, 'PointInTimeRecoverySpecification': {'PointInTimeRecoveryEnabled': False}}, 'Per-user job metadata and transactional active-job counters. On-demand avoids provisioned idle compute.', ['Every access must be partitioned by authenticated owner.'], retain=True)
    add('DeadLetters', 'SQS::Queue', {'SqsManagedSseEnabled':True,'MessageRetentionPeriod':1209600,'VisibilityTimeout':180}, 'Failed messages trigger terminal job state and release active-job quota.')
    add('Queue', 'SQS::Queue', {'SqsManagedSseEnabled':True,'VisibilityTimeout':1800,'MessageRetentionPeriod':86400,'RedrivePolicy':{'deadLetterTargetArn':get('DeadLetters','Arn'),'maxReceiveCount':3}}, 'Separate simulation execution from the 30-second HTTP integration.', ['Visibility timeout >= six times worker timeout.'])
    for q in ('Queue','DeadLetters'):
        add(q+'Policy','SQS::QueuePolicy',{'Queues':[ref(q)],'PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Deny','Principal':'*','Action':'sqs:*','Resource':get(q,'Arn'),'Condition':{'Bool':{'aws:SecureTransport':False}}}]}},'Require encrypted transport for queue access.')
    add('OriginAccess', 'CloudFront::OriginAccessControl', {'OriginAccessControlConfig': {'Name':sub('${AWS::StackName}-website'),'OriginAccessControlOriginType':'s3','SigningBehavior':'always','SigningProtocol':'sigv4'}}, 'Signed origin requests keep the website bucket private.')
    add('Headers','CloudFront::ResponseHeadersPolicy',{'ResponseHeadersPolicyConfig':{'Name':sub('${AWS::StackName}-security'),'SecurityHeadersConfig':{'ContentTypeOptions':{'Override':True},'FrameOptions':{'FrameOption':'DENY','Override':True},'ReferrerPolicy':{'ReferrerPolicy':'strict-origin-when-cross-origin','Override':True},'StrictTransportSecurity':{'AccessControlMaxAgeSec':31536000,'Override':True},'ContentSecurityPolicy':{'ContentSecurityPolicy':"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' data:; connect-src 'self' https://*.execute-api.us-east-2.amazonaws.com https://*.auth.us-east-2.amazoncognito.com; frame-ancestors 'none'; base-uri 'self'; object-src 'none'",'Override':True}}}},'Browser security headers for the exported application. Inline scripts are required by Next.js static hydration.')
    add('Distribution','CloudFront::Distribution',{'DistributionConfig':{'Enabled':True,'Comment':'Systems Lab static frontend','DefaultRootObject':'index.html','HttpVersion':'http2','PriceClass':'PriceClass_100','Origins':[{'Id':'website','DomainName':get('Website','RegionalDomainName'),'OriginAccessControlId':ref('OriginAccess'),'S3OriginConfig':{'OriginAccessIdentity':''}}],'DefaultCacheBehavior':{'TargetOriginId':'website','ViewerProtocolPolicy':'redirect-to-https','AllowedMethods':['GET','HEAD','OPTIONS'],'CachedMethods':['GET','HEAD'],'Compress':True,'ForwardedValues':{'QueryString':False,'Cookies':{'Forward':'none'}},'MinTTL':0,'DefaultTTL':60,'MaxTTL':86400,'ResponseHeadersPolicyId':ref('Headers')},'ViewerCertificate':{'CloudFrontDefaultCertificate':True}}},'Global HTTPS delivery for a static frontend; Python stays in the selected Region.')
    # Extend the TLS policy with a CloudFront-only read grant.
    resources['WebsitePolicy']['Properties']['PolicyDocument']['Statement'].append({'Effect':'Allow','Principal':{'Service':'cloudfront.amazonaws.com'},'Action':'s3:GetObject','Resource':sub('${Website.Arn}/*'),'Condition':{'StringEquals':{'AWS:SourceArn':sub('arn:${AWS::Partition}:cloudfront::${AWS::AccountId}:distribution/${Distribution}')}}})
    add('Users','Cognito::UserPool',{'UserPoolName':sub('${AWS::StackName}-users'),'UserPoolTier':'LITE','UsernameAttributes':['email'],'AutoVerifiedAttributes':['email'],'UsernameConfiguration':{'CaseSensitive':False},'Policies':{'PasswordPolicy':{'MinimumLength':12,'RequireLowercase':True,'RequireUppercase':True,'RequireNumbers':True,'RequireSymbols':False}},'AccountRecoverySetting':{'RecoveryMechanisms':[{'Name':'verified_email','Priority':1}]}},'Verified email sign-up and hosted OAuth sign-in.', ['No browser client secret; never export passwords or tokens.'], retain=True)
    add('LoginDomain','Cognito::UserPoolDomain',{'Domain':sub('systemslab-${AWS::AccountId}-${AWS::Region}'),'UserPoolId':ref('Users'),'ManagedLoginVersion':1},'Classic hosted UI avoids a paid branding dependency.')
    add('WebClient','Cognito::UserPoolClient',{'UserPoolId':ref('Users'),'ClientName':'systems-lab-browser','GenerateSecret':False,'SupportedIdentityProviders':['COGNITO'],'AllowedOAuthFlowsUserPoolClient':True,'AllowedOAuthFlows':['code'],'AllowedOAuthScopes':['openid','email'],'CallbackURLs':[sub('https://${Distribution.DomainName}/')],'LogoutURLs':[sub('https://${Distribution.DomainName}/')],'AccessTokenValidity':60,'IdTokenValidity':60,'RefreshTokenValidity':1,'TokenValidityUnits':{'AccessToken':'minutes','IdToken':'minutes','RefreshToken':'days'},'EnableTokenRevocation':True,'PreventUserExistenceErrors':'ENABLED'},'Public SPA uses authorization code with PKCE; tokens stay in browser session storage.')
    policy = lambda statements: {'Version':'2012-10-17','Statement':statements}
    allow = lambda actions, target: {'Effect':'Allow','Action':actions,'Resource':target}
    common = [allow(['dynamodb:GetItem','dynamodb:Query','dynamodb:PutItem','dynamodb:UpdateItem'],get('Jobs','Arn')),allow(['s3:GetObject'],sub('${Results.Arn}/results/*'))]
    for name, extras in [('Api',[allow(['sqs:SendMessage'],get('Queue','Arn'))]),('Worker',[allow(['sqs:ReceiveMessage','sqs:DeleteMessage','sqs:GetQueueAttributes'],[get('Queue','Arn'),get('DeadLetters','Arn')]),allow(['s3:PutObject'],sub('${Results.Arn}/results/*'))])]:
        add(name+'Role','IAM::Role',{'AssumeRolePolicyDocument':policy([{'Effect':'Allow','Principal':{'Service':'lambda.amazonaws.com'},'Action':'sts:AssumeRole'}]),'Policies':[{'PolicyName':'runtime','PolicyDocument':policy(common+extras+[allow(['logs:CreateLogStream','logs:PutLogEvents'],sub('arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:log-group:/aws/lambda/${AWS::StackName}-*:log-stream:*'))])}]},'Scoped service execution permissions; no human roles or administrative policies.')
    environment={'STORAGE_MODE':'aws','JOBS_TABLE':ref('Jobs'),'RESULTS_BUCKET':ref('Results'),'JOBS_QUEUE_URL':ref('Queue'),'SYSDESIGN_MAX_ARRIVALS':'150000','COGNITO_ISSUER':sub('https://cognito-idp.${AWS::Region}.amazonaws.com/${Users}'),'COGNITO_CLIENT_ID':ref('WebClient'),'COGNITO_DOMAIN':sub('https://${LoginDomain}.auth.${AWS::Region}.amazoncognito.com'),'ALLOWED_ORIGINS':sub('https://${Distribution.DomainName}')}
    for name,handler,memory,timeout,role in [('Api','main.handler',512,29,'ApiRole'),('Worker','worker.handler',1024,300,'WorkerRole'),('Recovery','worker.dead_letter_handler',256,30,'WorkerRole')]:
        add(name+'Logs','Logs::LogGroup',{'LogGroupName':sub('/aws/lambda/${AWS::StackName}-'+name.lower()),'RetentionInDays':7},'Bound diagnostic retention and avoid logging request bodies, credentials, or result data.')
        add(name+'Function','Lambda::Function',{'FunctionName':sub('${AWS::StackName}-'+name.lower()),'Runtime':'python3.12','Architectures':['x86_64'],'Handler':'fullstack.backend.'+handler,'Role':get(role,'Arn'),'Code':{'S3Bucket':ref('CodeBucket'),'S3Key':ref('CodeKey')},'MemorySize':memory,'Timeout':timeout,'Environment':{'Variables':environment}},'On-demand Python execution; no EC2, RDS, Redis, NAT gateway, or load balancer idle charges.', ['Keep regional resources in us-east-2; enforce owner and workload limits.'],DependsOn=[name+'Logs'])
    for source,fn in [('Queue','Worker'),('DeadLetters','Recovery')]:
        add(fn+'Mapping','Lambda::EventSourceMapping',{'EventSourceArn':get(source,'Arn'),'FunctionName':ref(fn+'Function'),'BatchSize':1,'Enabled':True,'ScalingConfig':{'MaximumConcurrency':2},**({'FunctionResponseTypes':['ReportBatchItemFailures']} if fn=='Worker' else {})},'Bound queue concurrency; partial failures are retried instead of losing experiments.')
    add('HttpApi','ApiGatewayV2::Api',{'Name':sub('${AWS::StackName}-api'),'ProtocolType':'HTTP','CorsConfiguration':{'AllowOrigins':[sub('https://${Distribution.DomainName}')],'AllowMethods':['GET','POST','OPTIONS'],'AllowHeaders':['authorization','content-type'],'MaxAge':600}},'HTTP API fronts FastAPI; app validates Cognito access tokens and enforces ownership.')
    add('Integration','ApiGatewayV2::Integration',{'ApiId':ref('HttpApi'),'IntegrationType':'AWS_PROXY','IntegrationUri':get('ApiFunction','Arn'),'PayloadFormatVersion':'2.0','TimeoutInMillis':29000},'HTTP requests submit or read jobs; never run the simulation inline.')
    add('Route','ApiGatewayV2::Route',{'ApiId':ref('HttpApi'),'RouteKey':'ANY /api/{proxy+}','Target':{'Fn::Join':['',['integrations/',ref('Integration')]]}},'Forward only the API path to FastAPI.')
    add('Stage','ApiGatewayV2::Stage',{'ApiId':ref('HttpApi'),'StageName':'$default','AutoDeploy':True,'DefaultRouteSettings':{'ThrottlingBurstLimit':5,'ThrottlingRateLimit':2}},'Small public-demo request limits bound bursts; they are not a monetary spending cap.')
    add('ApiPermission','Lambda::Permission',{'FunctionName':ref('ApiFunction'),'Action':'lambda:InvokeFunction','Principal':'apigateway.amazonaws.com','SourceAccount':ref('AWS::AccountId'),'SourceArn':sub('arn:${AWS::Partition}:execute-api:${AWS::Region}:${AWS::AccountId}:${HttpApi}/*/*/api/*')},'Only this project API may invoke the HTTP function.')
    return {'AWSTemplateFormatVersion':'2010-09-09','Description':'Systems Lab: private static website, authenticated FastAPI, queued SimPy workers and durable per-user results. Region us-east-2; local SQLite/PostgreSQL fallback is independent of AWS.','Metadata':{'AWSToolsMetrics':{'AWSAgentToolkit':'aws-cloudformation@3'},'com.aws.cloudformation.Context':{'ref':['fullstack/aws/DEPLOY.md'],'must':['No AWS Organizations or paid-plan upgrades. Deploy only after billing context is confirmed.']}},'Parameters':{'CodeBucket':{'Type':'String','AllowedPattern':'[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]'},'CodeKey':{'Type':'String','AllowedPattern':'packages/[A-Za-z0-9._/-]+\\.zip'}},'Resources':resources,'Outputs':{name:{'Value':value} for name,value in {'WebsiteUrl':sub('https://${Distribution.DomainName}'),'WebsiteBucket':ref('Website'),'ApiUrl':get('HttpApi','ApiEndpoint'),'ResultsBucket':ref('Results'),'JobsTable':ref('Jobs'),'UserPool':ref('Users'),'ClientId':ref('WebClient'),'DistributionId':ref('Distribution')}.items()}}


if __name__ == '__main__':
    destination=Path(__file__).with_name('template.json')
    destination.write_text(json.dumps(template(),indent=2)+'\n')
    print(destination)
